public function checkBanner($banner_id)
{
	$query = $this->db->query("SELECT * FROM ".DB_PREFIX."banner WHERE banner_id = '".(int)$banner_id."' AND status = '1'");

	if ($query->num_rows) return true;
	else return false;
}
